effect.shader:
// Perlin/fractal noise HSV colorizer — AM port of provided Shadertoy

// Hash helpers without uint bit tricks (for GLES compatibility)
float hash11(float n) {
  return fract(sin(n) * 43758.5453123);
}
float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float hash31(vec3 p) {
  return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123);
}

// Random unit vectors
vec2 randVec2(vec2 p){
  float a = hash21(p) * 6.28318530718; // 2*pi
  return vec2(cos(a), sin(a));
}
vec3 randVec3(vec3 p){
  float a = hash31(p);
  float b = hash31(p + 17.17);
  float theta = a * 6.28318530718;
  float phi = acos(1.0 - 2.0 * b);
  return vec3(sin(phi)*cos(theta), sin(phi)*sin(theta), cos(phi));
}

// Quintic smoother like in the code (x*x*x*((6x-15)x+10))
vec2 smooth2(vec2 x){ return x*x*x*((6.0*x - 15.0)*x + 10.0); }
vec3 smooth3(vec3 x){ return x*x*x*((6.0*x - 15.0)*x + 10.0); }

// 2D Perlin
float perlin2(vec2 p){
  vec2 ip = floor(p);
  vec2 f = fract(p);
  vec2 u = smooth2(f);

  vec2 g00 = randVec2(ip);
  vec2 g10 = randVec2(ip + vec2(1.0, 0.0));
  vec2 g01 = randVec2(ip + vec2(0.0, 1.0));
  vec2 g11 = randVec2(ip + vec2(1.0, 1.0));

  float n00 = dot(g00, f);
  float n10 = dot(g10, f - vec2(1.0, 0.0));
  float n01 = dot(g01, f - vec2(0.0, 1.0));
  float n11 = dot(g11, f - vec2(1.0, 1.0));

  float nx0 = mix(n00, n10, u.x);
  float nx1 = mix(n01, n11, u.x);
  float nxy = mix(nx0, nx1, u.y);
  // normalize to ~[0,1]
  return nxy * 1.41421356 * 0.5 + 0.5;
}

// 3D Perlin
float perlin3(vec3 p){
  vec3 ip = floor(p);
  vec3 f = fract(p);
  vec3 u = smooth3(f);

  vec3 g000 = randVec3(ip);
  vec3 g100 = randVec3(ip + vec3(1.0, 0.0, 0.0));
  vec3 g010 = randVec3(ip + vec3(0.0, 1.0, 0.0));
  vec3 g110 = randVec3(ip + vec3(1.0, 1.0, 0.0));
  vec3 g001 = randVec3(ip + vec3(0.0, 0.0, 1.0));
  vec3 g101 = randVec3(ip + vec3(1.0, 0.0, 1.0));
  vec3 g011 = randVec3(ip + vec3(0.0, 1.0, 1.0));
  vec3 g111 = randVec3(ip + vec3(1.0, 1.0, 1.0));

  float n000 = dot(g000, f);
  float n100 = dot(g100, f - vec3(1.0, 0.0, 0.0));
  float n010 = dot(g010, f - vec3(0.0, 1.0, 0.0));
  float n110 = dot(g110, f - vec3(1.0, 1.0, 0.0));
  float n001 = dot(g001, f - vec3(0.0, 0.0, 1.0));
  float n101 = dot(g101, f - vec3(1.0, 0.0, 1.0));
  float n011 = dot(g011, f - vec3(0.0, 1.0, 1.0));
  float n111 = dot(g111, f - vec3(1.0, 1.0, 1.0));

  float nx00 = mix(n000, n100, u.x);
  float nx10 = mix(n010, n110, u.x);
  float nx01 = mix(n001, n101, u.x);
  float nx11 = mix(n011, n111, u.x);
  float nxy0 = mix(nx00, nx10, u.y);
  float nxy1 = mix(nx01, nx11, u.y);
  float nxyz = mix(nxy0, nxy1, u.z);

  return nxyz * 1.154700538 * 0.5 + 0.5;
}

// Fractal sum (FBM) with adjustable lacunarity/gain
float fbm2(vec2 p, int oct){
  float sum = 0.0;
  float amp = 1.0;
  float tot = 0.0;
  float freq = 1.0;
  for(int i=0;i<8;i++){
    if(i>=oct) break;
    sum += perlin2(p*freq) * amp;
    tot += amp;
    freq *= lacunarity;
    amp *= gain;
  }
  return sum / max(tot, 1e-6);
}
float fbm3(vec3 p, int oct){
  float sum = 0.0;
  float amp = 1.0;
  float tot = 0.0;
  float freq = 1.0;
  for(int i=0;i<8;i++){
    if(i>=oct) break;
    sum += perlin3(p*freq) * amp;
    tot += amp;
    freq *= lacunarity;
    amp *= gain;
  }
  return sum / max(tot, 1e-6);
}

vec3 hsv2rgb(vec3 c){
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main(){
  // Make UV scale invariant like fragCoord/iResolution.y
  vec2 uv = acScreenNorm;
  uv.x *= acScreenSize.x / acScreenSize.y;

  int oct = int(clamp(float(octaves), 1.0, 8.0));
  float t = acTime * timeSpeed;
  vec3 p3 = vec3(uv * scale + seed, t);
  float n = fbm3(p3, oct);

  vec3 col;
  if(colorizeHSV){
    col = hsv2rgb(vec3(n * hueScale, clamp(saturation,0.0,1.0), value));
  } else {
    col = vec3(n);
  }

  vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
  vec3 outRGB = mix(src.rgb, col, clamp(blend, 0.0, 1.0));
  float a = src.a * alpha;
  gl_FragColor = vec4(outRGB, 1.0) * a;
}
